// ============================================================
// Voorraad Watch - kernberekening
// Input: producten, orders, retouren, merk-config
// Output: 1 item per maat-SKU met signaal
// ============================================================
const cfgRows   = $('Merk-config').all().map(i => i.json);
const prodPages = $('CE: producten (alle maten)').all().map(i => i.json);
const ordPages  = $('CE: orders 53 weken').all().map(i => i.json);
const retPages  = $('CE: retouren 53 weken').all().map(i => i.json);
const stkPages  = $('CE: voorraadmutaties').all().map(i => i.json);

const flat = (pages, k = 'Content') => pages.flatMap(p => p[k] || []);
const today = new Date();
const isoWeek = (d) => { const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate())); t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7)); const y = new Date(Date.UTC(t.getUTCFullYear(), 0, 1)); return Math.ceil(((t - y) / 86400000 + 1) / 7); };
const WEEK_NU = isoWeek(today);

// ---- merk-config indexeren ----
const cfg = {};
for (const r of cfgRows) if (r.merk) cfg[String(r.merk).trim().toLowerCase()] = r;
const DEFAULT = { levertijd_dagen: 30, veiligheidsvoorraad_weken: 2, max_woc: 26, seizoen_type: 'ALL', nabestellen_mogelijk: 'ja', doel_sell_through_pct: 70 };
const cfgFor = (merk) => ({ ...DEFAULT, ...(cfg[String(merk || '').trim().toLowerCase()] || {}) });

// ---- vraag opbouwen ----
const sold = {};   // mpn -> {w4, w13, w52, vorigJaarZelfdePeriode}
const bump = (mpn, veld, q) => { sold[mpn] = sold[mpn] || { w4: 0, w13: 0, w52: 0, ly: 0 }; sold[mpn][veld] += q; };
for (const o of flat(ordPages)) {
  const d = new Date(o.OrderDate); const dagen = (today - d) / 86400000;
  for (const l of o.Lines || []) {
    if (l.Status === 'CANCELED') continue;
    const q = l.Quantity || 0, mpn = l.MerchantProductNo;
    if (!mpn) continue;
    if (dagen <= 28)  bump(mpn, 'w4', q);
    if (dagen <= 91)  bump(mpn, 'w13', q);
    if (dagen <= 365) bump(mpn, 'w52', q);
    if (dagen > 337 && dagen <= 365) bump(mpn, 'ly', q);   // zelfde 4 weken vorig jaar
  }
}
// ---- laatste voorraadmutatie per artikel (vangt ook webshopverkoop) ----
const muteerde = {};
for (const s of flat(stkPages)) {
  const d = new Date(s.UpdatedAt);
  if (!isNaN(d)) muteerde[s.MerchantProductNo] = d;
}
const dagenStil = (mpn) => {
  const d = muteerde[mpn];
  return d ? Math.round((today - d) / 86400000) : null;
};

const retour = {};
for (const r of flat(retPages)) for (const l of r.Lines || []) { const m = l.MerchantProductNo; if (m) retour[m] = (retour[m] || 0) + (l.Quantity || 1); }

// ---- producten normaliseren (alleen varianten = maat-niveau) ----
const varianten = flat(prodPages).filter(p => p.ParentMerchantProductNo);
const ex = (p, k) => (p.ExtraData || []).find(e => e.Key === k)?.Value ?? null;
const seizoenVan = (s) => { s = (s || '').toLowerCase(); if (/herfst|winter|autumn/.test(s)) return 'FW'; if (/lente|zomer|spring|summer/.test(s)) return 'SS'; if (/alle|all/.test(s)) return 'ALL'; return 'ONBEKEND'; };

// ---- maatcurve per merk uit eigen verkoop ----
const curve = {};   // merk -> maat -> verkocht
for (const p of varianten) { const q = sold[p.MerchantProductNo]?.w52 || 0; if (!q) continue; const b = p.Brand || '?'; curve[b] = curve[b] || {}; curve[b][p.Size] = (curve[b][p.Size] || 0) + q; }

const out = [];
for (const p of varianten) {
  const c = cfgFor(p.Brand);
  const s = sold[p.MerchantProductNo] || { w4: 0, w13: 0, w52: 0, ly: 0 };
  const voorraad = p.Stock || 0;
  const inkoop = p.PurchasePrice || (p.Price || 0) * 0.45;
  const seizoen = seizoenVan(ex(p, 'seizoen_NL') || ex(p, 'seizoen_EN'));

  // vraag per week: 13 weken is de basis, 4 weken weegt zwaarder (recent signaal)
  const perWeek = (s.w13 / 13) * 0.6 + (s.w4 / 4) * 0.4;
  const woc = perWeek > 0 ? voorraad / perWeek : (voorraad > 0 ? 999 : 0);

  // hoeveel weken heeft dit artikel nog in zijn seizoen?
  const eindWeek = seizoen === 'FW' ? Number(c.fw_eind_week || 8) : seizoen === 'SS' ? Number(c.ss_eind_week || 30) : null;
  const weken_tot_eind = eindWeek === null ? null : ((eindWeek - WEEK_NU) + 52) % 52;

  // signaalhorizon = levertijd + veiligheid
  const horizon = Number(c.signaal_horizon_weken || (Number(c.levertijd_dagen) / 7 + Number(c.veiligheidsvoorraad_weken)));

  const stil = dagenStil(p.MerchantProductNo);

  let signaal = 'OK', actie = '', prioriteit = 0;
  if (voorraad === 0 && s.w13 > 0) {
    signaal = 'NEE-VERKOOP'; prioriteit = (s.w13 / 13) * (p.Price || 0) * 8;
    actie = c.nabestellen_mogelijk === 'nee' ? 'Niet nabestelbaar - vraag verplaatsen naar alternatief model' : `Bestellen: ~${Math.ceil(perWeek * horizon)} st`;
  } else if (woc < horizon && perWeek > 0) {
    signaal = 'TE-WEINIG'; prioriteit = (horizon - woc) * perWeek * (p.Price || 0);
    actie = `Bijbestellen ~${Math.ceil((horizon - woc) * perWeek)} st (dekking ${woc.toFixed(1)} wk < ${horizon.toFixed(1)} wk)`;
  } else if (weken_tot_eind !== null && perWeek > 0 && voorraad > perWeek * weken_tot_eind * 1.3) {
    const rest = Math.round(voorraad - perWeek * weken_tot_eind);
    signaal = 'TE-VEEL-SEIZOEN'; prioriteit = rest * inkoop;
    actie = `Blijft ~${rest} st over bij einde seizoen (wk ${eindWeek}) - nu afprijzen/spreiden`;
  } else if (woc > Number(c.max_woc)) {
    signaal = 'TE-VEEL'; prioriteit = (voorraad - perWeek * Number(c.max_woc)) * inkoop;
    actie = `Dekking ${woc >= 999 ? '>999' : woc.toFixed(0)} wk - kapitaal vast`;
  } else if (voorraad > 0 && s.w52 === 0 && stil !== null && stil > 90) {
    signaal = 'STIL'; prioriteit = voorraad * inkoop;
    actie = `Geen verkoop en ${stil} dagen geen voorraadmutatie - uitfaseren`;
  }

  out.push({ json: {
    peildatum: today.toISOString().slice(0, 10), week: WEEK_NU,
    merk: p.Brand, model: ex(p, 'model'), artikel: p.Name, parent: p.ParentMerchantProductNo,
    ean: p.MerchantProductNo, maat: p.Size, kleur: p.Color,
    seizoen, seizoensjaar: ex(p, 'Seizoensjaar'),
    voorraad, verkocht_4w: s.w4, verkocht_13w: s.w13, verkocht_52w: s.w52, vorig_jaar_4w: s.ly,
    retour_52w: retour[p.MerchantProductNo] || 0,
    retour_pct: s.w52 ? Math.round(100 * (retour[p.MerchantProductNo] || 0) / s.w52) : null,
    dagen_sinds_mutatie: stil,
    vraag_per_week: Number(perWeek.toFixed(2)),
    weken_voorraad: woc >= 999 ? null : Number(woc.toFixed(1)),
    weken_tot_seizoenseinde: weken_tot_eind,
    signaal_horizon_weken: Number(horizon.toFixed(1)),
    verkoopprijs: p.Price, inkoopprijs: Number(inkoop.toFixed(2)),
    voorraadwaarde: Number((voorraad * inkoop).toFixed(2)),
    signaal, actie, prioriteit_eur: Math.round(prioriteit),
  } });
}

out.sort((a, b) => b.json.prioriteit_eur - a.json.prioriteit_eur);
return out;

// Bouwt het weekrapport per merk
const rows = $input.all().map(i => i.json);
const perMerk = {};
for (const r of rows) {
  const m = perMerk[r.merk] = perMerk[r.merk] || { merk: r.merk, waarde: 0, teweinig: 0, teveel: 0, dead: 0, nee_verkoop: 0, top: [] };
  m.waarde += r.voorraadwaarde;
  if (r.signaal === 'TE-WEINIG') m.teweinig++;
  if (r.signaal === 'TE-VEEL' || r.signaal === 'TE-VEEL-SEIZOEN') m.teveel += r.prioriteit_eur;
  if (r.signaal === 'DEAD') m.dead += r.prioriteit_eur;
  if (r.signaal === 'NEE-VERKOOP') m.nee_verkoop++;
  if (r.signaal !== 'OK' && m.top.length < 10) m.top.push(r);
}
const merken = Object.values(perMerk).sort((a, b) => b.waarde - a.waarde);
const eur = n => '\u20ac ' + Math.round(n).toLocaleString('nl-NL');
let html = `<h2>Voorraad Watch \u2013 week ${rows[0]?.week}</h2>`;
html += '<table border=1 cellpadding=6 style="border-collapse:collapse"><tr><th>Merk</th><th>Voorraadwaarde</th><th>Maten te weinig</th><th>Nul-voorraad met vraag</th><th>Overstock \u20ac</th><th>Dead \u20ac</th></tr>';
for (const m of merken) html += `<tr><td>${m.merk}</td><td>${eur(m.waarde)}</td><td>${m.teweinig}</td><td>${m.nee_verkoop}</td><td>${eur(m.teveel)}</td><td>${eur(m.dead)}</td></tr>`;
html += '</table><h3>Top acties deze week</h3><ol>';
for (const r of rows.filter(r => r.signaal !== 'OK').slice(0, 25)) html += `<li><b>${r.merk}</b> \u2013 ${r.artikel} maat ${r.maat}: <b>${r.signaal}</b> \u2013 ${r.actie} <i>(${eur(r.prioriteit_eur)})</i></li>`;
html += '</ol>';
return [{ json: { html, week: rows[0]?.week } }];
